<?php
session_start(); require_once '../conexion.php';
if (!isset($_SESSION['usuario_id']) || $_SESSION['rol'] !== 'admin') { header('Location: ../login.php'); exit; }
$id=isset($_GET['id'])?(int)$_GET['id']:0; if($id<=0){header('Location: operarios.php?error='.urlencode('Operario inválido.'));exit;}
$stmt=$conexion->prepare("SELECT id,nombre,usuario,estado FROM usuarios WHERE id=? AND rol='operario'"); $stmt->bind_param('i',$id);$stmt->execute();$resultado=$stmt->get_result();if($resultado->num_rows!==1){$stmt->close();header('Location: operarios.php?error='.urlencode('Operario no encontrado.'));exit;}$operario=$resultado->fetch_assoc();$stmt->close();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $nombre=isset($_POST['nombre'])?trim($_POST['nombre']):'';$usuario=isset($_POST['usuario'])?trim($_POST['usuario']):'';$password=isset($_POST['password'])?$_POST['password']:'';$estado=isset($_POST['estado'])?(int)$_POST['estado']:1;
 if($nombre===''||$usuario===''){$error='Nombre y usuario son obligatorios.';}else{
  if($password!==''){$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=$conexion->prepare("UPDATE usuarios SET nombre=?,usuario=?,password=?,estado=? WHERE id=? AND rol='operario'");$stmt->bind_param('sssii',$nombre,$usuario,$hash,$estado,$id);}else{$stmt=$conexion->prepare("UPDATE usuarios SET nombre=?,usuario=?,estado=? WHERE id=? AND rol='operario'");$stmt->bind_param('ssii',$nombre,$usuario,$estado,$id);}
  if($stmt->execute()){$stmt->close();header('Location: operarios.php?mensaje='.urlencode('Operario modificado correctamente.'));exit;}$error=($stmt->errno==1062)?'Ese usuario ya existe.':'No se pudo modificar: '.$stmt->error;$stmt->close();
 }
 $operario['nombre']=$nombre;$operario['usuario']=$usuario;$operario['estado']=$estado;
}
?>
