ario['estado']===1){echo 'selected';}?>>Activo</option><option value="0" <?php if((int)$operario['estado']===0){echo 'selected';}?>>Inactivo</option></select></div><button type="submit" class="btn-picking"><i class="bi bi-save"></i> Guardar cambios</button></form></div></main></body></html>
